<?php $title='Historique du stock'; $subtitle='Mouvements enregistrés pour ce produit.'; $section='shop'; require __DIR__.'/management_header.php';
$url=static fn(int $p): string => 'stock_history?'.http_build_query(['id'=>(int)$product['id'],'from'=>$filters['from'],'to'=>$filters['to'],'reason'=>$filters['reason'],'p'=>$p]); ?>
<section class="card management-table"><div class="card-head"><div><h3><?= e($product['name']) ?> · <?= e($product['sku']) ?></h3><p>Stock actuel : <?= (int)$product['stock'] ?> · <?= $product['is_active'] ? 'Actif' : 'Inactif' ?> · <?= (int)$history['total'] ?> mouvement(s)</p></div><a class="text-link" href="shop?product=<?= (int)$product['id'] ?>">← Produit</a></div>
<form method="get" action="stock_history" class="search-form"><input type="hidden" name="id" value="<?= (int)$product['id'] ?>"><label>Du <input type="date" name="from" min="1900-01-01" max="2099-12-31" value="<?= e($filters['from']) ?>"></label><label>Au <input type="date" name="to" min="1900-01-01" max="2099-12-31" value="<?= e($filters['to']) ?>"></label><label>Type <select name="reason"><option value="">Tous</option><?php foreach (StockHistory::REASONS as $key=>$label): ?><option value="<?= e($key) ?>" <?= $filters['reason']===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="primary">Filtrer</button><a class="text-link" href="stock_history?id=<?= (int)$product['id'] ?>">Effacer</a></form>
<?php if (!$error): ?><form method="post" action="stock_history_export" class="activity-export"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$product['id'] ?>"><?php foreach (['from','to','reason'] as $key): ?><input type="hidden" name="<?= e($key) ?>" value="<?= e($filters[$key]) ?>"><?php endforeach; ?><button class="btn btn-outline" type="submit">Exporter les résultats en CSV</button></form><div class="table-scroll"><table><thead><tr><th>DATE</th><th>TYPE</th><th>ÉCART</th><th>MOTIF</th><th>SAISI PAR</th><th>VENTE</th></tr></thead><tbody><?php foreach ($history['rows'] as $row): ?><tr><td><?= e(date('d/m/Y H:i',strtotime($row['created_at']))) ?></td><td><?= e(StockHistory::REASONS[$row['reason']] ?? $row['reason']) ?></td><td><?= (int)$row['quantity_change']>0 ? '+' : '' ?><?= (int)$row['quantity_change'] ?></td><td><?= e($row['note'] ?: '—') ?></td><td><?= e($row['author'] ?: '—') ?></td><td><?php if ($row['sale_id']): ?><a class="text-link" href="shop_receipt?id=<?= (int)$row['sale_id'] ?>">Reçu #<?= (int)$row['sale_id'] ?></a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if (!$history['rows']): ?><tr><td colspan="6" class="empty">Aucun mouvement pour ces critères.</td></tr><?php endif; ?></tbody></table></div><nav class="pagination" aria-label="Pages des mouvements"><?php if ($history['page']>1): ?><a href="<?= e($url($history['page']-1)) ?>">← Précédent</a><?php endif; ?><span>Page <?= (int)$history['page'] ?> / <?= (int)$history['pages'] ?></span><?php if ($history['page']<$history['pages']): ?><a href="<?= e($url($history['page']+1)) ?>">Suivant →</a><?php endif; ?></nav><?php endif; ?><p class="form-hint">Les informations produit et le stock sont les valeurs actuelles. Les auteurs sont affichés selon leur nom actuel ; les mouvements antérieurs à leur enregistrement ne sont pas reconstitués.</p></section>
<?php require __DIR__.'/management_footer.php'; ?>
